      pt: ["Sede: Lipik", "Clientes: Bentley, Lamborghini", "Tipo: Vidro especial", "Exportação: 95 %"],
      fr: ["Siège : Lipik", "Clients : Bentley, Lamborghini", "Type : Verre spécial", "Exportation : 95 %"],
